export const FAB_4: IndexPlay[] = [
  { id: 'R14v10', hand: hard(14), up: 10, index: 3, atOrAbove: 'surrender', below: 'hit', surrender: true, source: 'Fab4' },
  { id: 'R15v10', hand: hard(15), up: 10, index: 0, atOrAbove: 'surrender', below: 'hit', surrender: true, source: 'Fab4' },
  { id: 'R15v9', hand: hard(15), up: 9, index: 2, atOrAbove: 'surrender', below: 'hit', surrender: true, source: 'Fab4' },
  { id: 'R15vA', hand: hard(15), up: 1, index: 1, atOrAbove: 'surrender', below: 'hit', surrender: true, source: 'Fab4' },
];

export const REFERENCE_INDICES: IndexPlay[] = [...ILLUSTRIOUS_18, ...FAB_4];

function handOf(values: readonly number[]) {
  let sum = 0;
  let ace = false;
  for (const v of values) {
    sum += v;
    if (v === 1) ace = true;
  }
  const soft = ace && sum + 10 <= 21;
  return { total: soft ? sum + 10 : sum, soft, pair: values.length === 2 && values[0] === values[1] };
}

export function matches(spec: HandSpec, values: readonly number[]): boolean {
  const h = handOf(values);
  switch (spec.kind) {
    case 'hard':
      return !h.soft && h.total === spec.total && !(h.pair && values[0] === 10 && spec.total === 20);
    case 'soft':
      return h.soft && h.total === spec.total;
    case 'pair':
      return h.pair && values[0] === spec.value;
    case 'insurance':
      return false;
  }
}

function resolve(a: Action, av: Avail): Action | null {
  if (a === 'double' && !av.canDouble) return null;
  if (a === 'split' && !av.canSplit) return null;
  if (a === 'surrender' && !av.canSurrender) return null;
  return a;
}

/**
 * Play with indices: surrender indices first (when offered), then other matching index plays, else the chart.
 * Pairs the chart splits are not overridden by hard-total indices (8,8 is a split, not a hard 16).
 */
export function indexAction(plays: IndexPlay[], chart: Chart, hand: readonly number[], up: number, tc: number, av: Avail): { action: Action; play?: IndexPlay } {
  const base = chartAction(chart, hand, up, av);
  const isPair = hand.length === 2 && hand[0] === hand[1];
  const cands = plays.filter((p) => p.hand.kind !== 'insurance' && p.up === up && matches(p.hand, hand));
  const ordered = [...cands.filter((p) => p.surrender), ...cands.filter((p) => !p.surrender)];
  for (const p of ordered) {
    if (p.surrender && !av.canSurrender) continue;
    if (isPair && base === 'split' && p.hand.kind !== 'pair') continue;
    if (p.hand.kind !== 'pair' && (p.atOrAbove === 'double' || p.below === 'double') && hand.length !== 2) continue;
    const want = tc >= p.index ? p.atOrAbove : p.below;
    if (want === 'insure' || want === 'noinsure') continue;
    // A surrender play's "below" branch defers to the other plays/chart.
    if (p.surrender && tc < p.index) continue;
    const r = resolve(want, av);
    if (r) return { action: r, play: p };
  }
  return { action: base };
}

export function insuranceDecision(plays: IndexPlay[], tc: number): { take: boolean; play?: IndexPlay } {
  const p = plays.find((x) => x.hand.kind === 'insurance');
  if (!p) return { take: false };
  return { take: tc >= p.index, play: p };
}

export function playLabel(p: IndexPlay): string {
  const up = p.up === 1 ? 'A' : p.up === 10 ? 'T' : String(p.up);
  switch (p.hand.kind) {
    case 'insurance':
      return 'Insurance';
    case 'hard':
      return `${p.surrender ? 'Surr ' : ''}${p.hand.total} v ${up}`;
    case 'soft':
      return `A,${p.hand.total - 11} v ${up}`;
    case 'pair': {
      const v = p.hand.value === 1 ? 'A' : p.hand.value === 10 ? 'T' : String(p.hand.value);
      return `${v},${v} v ${up}`;
    }
  }
}
